names = ['sneaker', 'white sneaker', 'green shoe', 'teal shoe', 'other shoe', 'second shoe', 'shelf', 'white shelf', 'shoe shelf', 'rack', 'shoe rack', 'wooden rack', 'cabinet']
for n in names:
    r = primitives.call(name='submit_capx_action', action='get_object_pose', native_api=True, parameters={'object_name': n, 'return_bbox_extent': True})
    res = None
    if r.ok and isinstance(r.output, dict):
        res = r.output.get('native_api_result')
    if res is not None and len(res) > 2 and res[0] is not None:
        p = res[0].get('values') if isinstance(res[0], dict) else res[0]
        e = res[2].get('values') if isinstance(res[2], dict) else res[2]
        print(n, 'POS', p, 'EXT', e)
    else:
        print(n, 'NONE')

r_b = primitives.call(name='submit_capx_action', action='get_object_pose', native_api=True, parameters={'object_name': 'brown shoe', 'return_bbox_extent': True})
resb = None
if r_b.ok and isinstance(r_b.output, dict):
    resb = r_b.output.get('native_api_result')
if resb is not None and resb[0] is not None:
    print('brown', resb[0].get('values'), resb[2].get('values'))
else:
    print('brown NONE')
r_g = primitives.call(name='submit_capx_action', action='sample_grasp_pose', native_api=True, parameters={'object_name': 'shoe'})
resg = None
if r_g.ok and isinstance(r_g.output, dict):
    resg = r_g.output.get('native_api_result')
print('sample type', type(resg))
if isinstance(resg, list) and len(resg) == 2:
    pres = resg[0]
    gs = resg[1]
    print('counts', len(pres), len(gs))
    for i in range(len(pres)):
        print(i, pres[i], gs[i])
else:
    print('resg', resg)

def vals(h):
    if isinstance(h, dict):
        return h.get('values')
    return h

def pose_pair(p):
    if isinstance(p, list) and len(p) == 2:
        return [vals(p[0]), vals(p[1])]
    if isinstance(p, dict):
        return [vals(p.get('position')), vals(p.get('quaternion'))]
    return None

r_g = primitives.call(name='submit_capx_action', action='sample_grasp_pose', native_api=True, parameters={'object_name': 'shoe'})
resg = None
if r_g.ok and isinstance(r_g.output, dict):
    resg = r_g.output.get('native_api_result')
held = False
if resg is not None and len(resg) == 2:
    pre_list = resg[0]
    gr_list = resg[1]
    print('n_candidates', len(pre_list), len(gr_list))
    for idx in [1, 0]:
        pp = pose_pair(pre_list[idx])
        gp = pose_pair(gr_list[idx])
        print('try', idx, pp, gp)
        if pp is None or gp is None:
            continue
        r_gr = primitives.call(name='submit_capx_action', action='grasp_object', native_api=True, parameters={'pregrasp_pose': pp, 'grasp_pose': gp, 'object_name': 'shoe', 'arm': 1, 'max_steps': 40})
        print('grasp_ok', r_gr.ok, r_gr.output)
        r_chk = primitives.call(name='submit_capx_action', action='check_object_in_hand', native_api=True, parameters={'arm': 1})
        nv = None
        if r_chk.ok and isinstance(r_chk.output, dict):
            nv = r_chk.output.get('native_api_result')
        if nv is True:
            held = True
        elif isinstance(nv, dict) and nv.get('values') is True:
            held = True
        elif isinstance(nv, list) and len(nv) > 0:
            v0 = nv[0]
            if v0 is True or (isinstance(v0, dict) and v0.get('values') is True):
                held = True
        print('held_after', idx, held)
        if held:
            break
else:
    print('no grasp candidates', resg)
print('HELD', held)

